import json
import threading
from http.server import BaseHTTPRequestHandler, HTTPServer

from harness.model import OpenAICompatModel

SEEN = {}


class Stub(BaseHTTPRequestHandler):
    def do_POST(self):
        SEEN["path"] = self.path
        SEEN["auth"] = self.headers["Authorization"]
        SEEN["body"] = json.loads(self.rfile.read(int(self.headers["Content-Length"])))
        reply = {
            "choices": [
                {
                    "message": {
                        "content": None,
                        "tool_calls": [
                            {
                                "id": "call_1",
                                "type": "function",
                                "function": {
                                    "name": "read_file",
                                    "arguments": '{"path": "calc.py"}',
                                },
                            }
                        ],
                    }
                }
            ],
            "usage": {"prompt_tokens": 120, "completion_tokens": 15},
        }
        data = json.dumps(reply).encode()
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def log_message(self, *args):
        pass


def test_openai_compatible_adapter_round_trip():
    server = HTTPServer(("127.0.0.1", 0), Stub)
    threading.Thread(target=server.serve_forever, daemon=True).start()
    model = OpenAICompatModel(f"http://127.0.0.1:{server.server_port}/v1", "test-key", "any-model")
    reply = model.complete(
        [{"role": "user", "content": "hi"}],
        [{"name": "read_file", "description": "d", "parameters": {"type": "object"}}],
    )
    server.shutdown()
    assert SEEN["path"] == "/v1/chat/completions" and SEEN["auth"] == "Bearer test-key"
    assert SEEN["body"]["tools"][0]["type"] == "function"
    assert reply.tool_calls[0].name == "read_file" and reply.tool_calls[0].args == {
        "path": "calc.py"
    }
    assert (reply.input_tokens, reply.output_tokens) == (120, 15)
